<template>
  <div class="mall-page" :class="{ 'edit-page': editPage }">
    <template v-if="editPage">
      <el-page-header :content="editingId ? '编辑积分商品' : '添加积分商品'" @back="backToList" />
      <el-card class="edit-card !border-none mt-4" shadow="never">
        <el-form :model="form" label-width="100px">
          <el-divider content-position="left">基本信息</el-divider>
          <el-row :gutter="24"><el-col :span="24"><el-form-item label="商品轮播图"><div class="image-grid"><div v-for="(image,index) in form.images" :key="image" class="image-item"><el-image :src="image" fit="cover" /><el-button circle size="small" type="danger" class="remove-image" @click="removeImage(index)">×</el-button></div><label v-if="form.images.length < 9" class="upload-trigger"><input type="file" accept="image/*" multiple @change="uploadImages"><span>+</span><small>上传图片</small></label></div></el-form-item></el-col><el-col :span="12"><el-form-item label="商品名称" required><el-input v-model="form.name" /></el-form-item></el-col><el-col :span="12"><el-form-item label="限量"><el-input v-model="form.limit" /></el-form-item></el-col><el-col :span="12"><el-form-item label="排序"><el-input v-model="form.sort" /></el-form-item></el-col><el-col :span="12"><el-form-item label="上架状态"><el-select v-model="form.status"><el-option label="上架" value="上架" /><el-option label="下架" value="下架" /></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="热门推荐"><el-switch v-model="form.hot" active-text="推荐" inactive-text="不推荐" /></el-form-item></el-col><el-col :span="12"><el-form-item label="库存"><el-input v-model="form.stock" /></el-form-item></el-col></el-row>
          <el-divider content-position="left">运费配置</el-divider>
          <el-row :gutter="24"><el-col :span="8"><el-form-item label="重量"><el-input v-model="form.weight"><template #append>kg</template></el-input></el-form-item></el-col><el-col :span="8"><el-form-item label="体积"><el-input v-model="form.volume"><template #append>m³</template></el-input></el-form-item></el-col><el-col :span="8"><el-form-item label="配送方式"><el-select v-model="form.delivery"><el-option label="包邮" value="包邮" /><el-option label="统一运费" value="统一运费" /><el-option label="运费模板" value="运费模板" /></el-select></el-form-item></el-col><el-col v-if="form.delivery === '统一运费'" :span="8"><el-form-item label="运费金额" required><el-input v-model="form.freightFee"><template #append>元</template></el-input></el-form-item></el-col><el-col v-if="form.delivery === '运费模板'" :span="8"><el-form-item label="运费模板" required><el-select v-model="form.freightTemplate" placeholder="请选择模板"><el-option v-for="item in freightTemplates" :key="item" :label="item" :value="item" /></el-select></el-form-item></el-col></el-row>
          <el-divider content-position="left">商品详情</el-divider><Editor v-model="form.detail" height="320px" />
          <div class="form-actions"><el-button @click="backToList">取消</el-button><el-button type="primary" @click="save">保存商品</el-button></div>
        </el-form>
      </el-card>
    </template>
    <template v-else>
      <el-card shadow="never" class="!border-none"><el-form :model="filters" inline class="filter-form"><el-form-item label="创建时间"><el-date-picker v-model="filters.dateRange" type="daterange" value-format="YYYY-MM-DD" range-separator="至" start-placeholder="开始日期" end-placeholder="结束日期" /></el-form-item><el-form-item label="商品搜索"><el-input v-model="filters.keyword" clearable placeholder="商品名称" /></el-form-item><el-form-item label="商品分类"><el-select v-model="filters.category" clearable placeholder="全部分类"><el-option v-for="item in categories" :key="item" :label="item" :value="item" /></el-select></el-form-item><el-form-item><el-button type="primary" @click="resetPage">查询</el-button><el-button @click="resetFilters">重置</el-button></el-form-item></el-form></el-card>
      <el-card shadow="never" class="!border-none mt-4"><template #header><div class="heading"><el-tabs v-model="filters.tab" class="status-tabs" @tab-change="resetPage"><el-tab-pane v-for="tab in tabs" :key="tab" :label="`${tab}（${tabCount(tab)}）`" :name="tab" /></el-tabs><div><el-button type="primary" @click="openForm()">添加商品</el-button><el-button @click="exportData">导出</el-button></div></div></template><el-table :data="pagedRows" stripe table-layout="fixed"><el-table-column prop="id" label="ID" min-width="120" /><el-table-column label="商品图片" width="90"><template #default="{row}"><el-image :src="row.image" class="thumb" fit="cover" /></template></el-table-column><el-table-column prop="name" label="商品名称" min-width="170" /><el-table-column prop="category" label="商品分类" min-width="120" /><el-table-column prop="points" label="兑换积分" min-width="110" /><el-table-column prop="limit" label="限量" min-width="80" /><el-table-column prop="stock" label="库存" min-width="90" /><el-table-column prop="status" label="状态" min-width="90" /><el-table-column prop="sort" label="排序" min-width="80" /><el-table-column prop="createdAt" label="创建时间" min-width="170" /><el-table-column label="操作" width="190" fixed="right"><template #default="{row}"><template v-if="row.status==='回收站'"><el-button link type="success" @click="restore(row)">恢复</el-button><el-button link type="danger" @click="permanentDelete(row)">彻底删除</el-button></template><template v-else><el-button link type="primary" @click="openForm(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="page" background layout="total,prev,pager,next" :total="filteredRows.length" /></div></el-card>
    </template>
  </div>
</template>
<script setup lang="ts" name="pointsMallGoods">
import { useRoute, useRouter } from 'vue-router'; import Editor from '@/components/editor/index.vue'
const freightTemplates = ['测试模板']
const route=useRoute();const router=useRouter();const editPage=computed(()=>route.query.action==='add'||route.query.action==='edit');const editingId=ref('');const categories=['饮料','休闲食品','日用百货','礼品礼盒'];const tabs=['全部','上架','下架','回收站'];const filters=reactive({keyword:'',category:'',dateRange:[] as string[],tab:'全部'});const page=ref(1);const form=reactive<any>({name:'',category:'饮料',limit:1,sort:0,status:'上架',hot:false,stock:100,points:100,weight:1,volume:0.02,delivery:'包邮',detail:'',images:[]});const emptyForm=()=>({name:'',category:'饮料',limit:1,sort:0,status:'上架',hot:false,stock:100,points:100,weight:1,volume:0.02,delivery:'包邮',detail:'',images:[]});const goods=reactive<any[]>(Array.from({length:24},(_,i)=>{const image=`https://images.unsplash.com/${['photo-1544145945-f90425340c7e','photo-1505253716362-afaea1d3d1af'][i%2]}?auto=format&fit=crop&w=100&q=80`;return{id:`JFSP${1001+i}`,name:['茶饮礼盒','坚果大礼包','保温杯','零食组合'][i%4],category:categories[i%4],points:100+i*20,limit:1+i%3,stock:80+i*6,createdAt:`2026-08-${String(28-i%20).padStart(2,'0')} 10:20:00`,sort:100-i,status:i===7?'回收站':i%5?'上架':'下架',hot:i%4===0,image,images:[image],weight:1,volume:0.02,delivery:'包邮',detail:'<p>精选积分兑换商品</p>'}}));const filteredRows=computed(()=>goods.filter(r=>(filters.tab==='全部'||r.status===filters.tab)&&(!filters.keyword||r.name.includes(filters.keyword.trim()))&&(!filters.category||r.category===filters.category)&&(filters.dateRange.length!==2||(r.createdAt.slice(0,10)>=filters.dateRange[0]&&r.createdAt.slice(0,10)<=filters.dateRange[1]))));const pagedRows=computed(()=>filteredRows.value.slice((page.value-1)*10,page.value*10));const tabCount=(t:string)=>t==='全部'?goods.length:goods.filter(r=>r.status===t).length;const resetPage=()=>page.value=1;const resetFilters=()=>{Object.assign(filters,{keyword:'',category:'',dateRange:[],tab:'全部'});resetPage()};const openForm=(r?:any)=>{editingId.value=r?.id||'';Object.assign(form,r?{...r,images:[...r.images]}:emptyForm());router.push({query:{action:r?'edit':'add',...(r?{id:r.id}:{})}})};const backToList=()=>router.push({path:route.path});const uploadImages=(e:Event)=>{const files=Array.from((e.target as HTMLInputElement).files||[]).slice(0,9-form.images.length);files.forEach(f=>form.images.push(URL.createObjectURL(f)))};const removeImage=(i:number)=>{const img=form.images.splice(i,1)[0];if(img?.startsWith('blob:'))URL.revokeObjectURL(img)};const save=()=>{if(!form.name.trim())return ElMessage.error('请输入商品名称');if(editingId.value){const r=goods.find(x=>x.id===editingId.value);if(r)Object.assign(r,form)}else goods.unshift({...form,id:`JFSP${Date.now()}`,createdAt:'2026-08-28 17:30:00',image:form.images[0]||'https://images.unsplash.com/photo-1544145945-f90425340c7e?auto=format&fit=crop&w=100&q=80'});ElMessage.success('积分商品已保存');backToList()};const remove=async(r:any)=>{try{await ElMessageBox.confirm(`确认删除商品“${r.name}”吗？删除后将进入回收站`,'删除确认',{type:'warning'});r.status='回收站';ElMessage.success('商品已移入回收站')}catch{}};const restore=async(r:any)=>{try{await ElMessageBox.confirm(`确认恢复商品“${r.name}”吗？将恢复为下架状态`,'恢复确认',{type:'warning'});r.status='下架';ElMessage.success('商品已恢复')}catch{}};const permanentDelete=async(r:any)=>{try{await ElMessageBox.confirm(`确认彻底删除商品“${r.name}”吗？不可恢复`,'彻底删除',{type:'error'});goods.splice(goods.indexOf(r),1);ElMessage.success('商品已彻底删除')}catch{}};const exportData=()=>{const data=[['ID','商品名称','商品分类','兑换积分','状态','排序','创建时间'],...filteredRows.value.map(r=>[r.id,r.name,r.category,r.points,r.status,r.sort,r.createdAt])];const url=URL.createObjectURL(new Blob([`\ufeff${data.map(r=>r.join(',')).join('\n')}`],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='积分商品.csv';a.click();URL.revokeObjectURL(url)}
</script>
<style scoped>.mall-page{min-height:100%}.edit-page{min-height:100%;padding:24px;background:#fff}.edit-card{max-width:none;border:none}.edit-card :deep(.el-card__body){padding:24px 0}.edit-card :deep(.el-divider){margin:26px 0 20px}.edit-card :deep(.el-form-item){margin-bottom:20px}.edit-card :deep(.el-input),.edit-card :deep(.el-select){width:100%;max-width:360px}.edit-card :deep(.el-divider__text){font-size:15px;font-weight:600}.filter-form{margin-bottom:-18px}.filter-form :deep(.el-input),.filter-form :deep(.el-select){width:210px}.filter-form :deep(.el-date-editor){width:280px}.heading{display:flex;justify-content:space-between;align-items:center}.status-tabs :deep(.el-tabs__header){margin:0}.status-tabs :deep(.el-tabs__nav-wrap::after){display:none}.thumb{width:52px;height:52px;border-radius:5px}.pagination{display:flex;justify-content:flex-end;margin-top:16px}.image-grid{display:flex;gap:14px;flex-wrap:wrap}.image-item,.upload-trigger{width:100px;height:100px;position:relative}.image-item :deep(.el-image){width:100px;height:100px;border-radius:6px}.upload-trigger{display:flex;flex-direction:column;align-items:center;justify-content:center;border:1px dashed var(--el-border-color);color:var(--el-text-color-secondary);cursor:pointer}.upload-trigger input{display:none}.upload-trigger span{font-size:28px}.remove-image{position:absolute;top:-8px;right:-8px;z-index:2}.form-actions{display:flex;justify-content:center;gap:12px;margin-top:30px;padding-top:20px;border-top:1px solid #f0f2f5}@media(max-width:700px){.edit-page{padding:16px}.edit-card :deep(.el-card__body){padding:16px 0}.filter-form :deep(.el-input),.filter-form :deep(.el-select),.filter-form :deep(.el-date-editor){width:100%}.filter-form :deep(.el-form-item){width:100%;margin-right:0}.edit-card :deep(.el-col){width:100%;max-width:100%;flex:0 0 100%}}</style>
